class StrictInt(int):
    def __eq__(self, other):
        if isinstance(other, bool) and not isinstance(self, bool):
            # mimic int equality for bool: int value compare
            return int.__eq__(int(self), int(other))
        if not isinstance(other, int):
            return False
        return int.__eq__(int(self), int(other))
    def __ne__(self, other):
        r = self.__eq__(other)
        return not r
    __hash__ = int.__hash__

def solve(a, x):
    import bisect
    try:
        idx = bisect.bisect_left(a, x)
    except Exception:
        # fallback manual
        lo, hi = 0, len(a)
        while lo < hi:
            mid = (lo+hi)//2
            if a[mid] < x:
                lo = mid+1
            else:
                hi = mid
        idx = lo
    return StrictInt(idx)

